attrs.style:
font-size: clamp(24px, 2.5vw, 32px);
font-weight: 500;
line-height: 1.55;
text-align: center;
margin: 40px auto 32px;

css:
.gh-lead {
    max-width: 800px;
    margin: 0 auto;
    text-align: left !important;
}

.gh-lead p {
    text-align: left !important;
}
/* 「本当はこうしたい」から始まる文章だけ左揃え */
p.gh-hero-copy {
    text-align: left !important;
}
/* 文章全体は中央、文字は左揃え */
.gh-intro {
    width: fit-content;
    max-width: 100%;
    margin: 0 auto 28px;
    text-align: left;
    line-height: 2;
}


.gh-bansou-course {
  --gh-green: #8fa78b;
  --gh-green-pale: #e8eee5;
  --gh-cream: #faf8f1;
  --gh-cream-light: #fcfbf7;
  --gh-text: #555d59;
  --gh-line: #d8e0d4;
  color: var(--gh-text);
  font-family: "Zen Maru Gothic", "Hiragino Maru Gothic ProN", "Yu Gothic", Meiryo, sans-serif;
  font-size: 16px;
  line-height: 2;
  letter-spacing: 0.035em;
}

.gh-bansou-course,
.gh-bansou-course * {
  box-sizing: border-box;
}

.gh-bansou-course .gh-inner {
  width: min(100%, 1080px);
  margin: 0 auto;
}

.gh-bansou-course .gh-hero {
  margin-bottom: 56px;
  padding: 72px 32px;
  text-align: center;
  background: linear-gradient(135deg, var(--gh-cream-light), var(--gh-cream));
  border-top: 3px solid var(--gh-green);
  border-radius: 0 0 26px 26px;
}

.gh-bansou-course .gh-eyebrow {
  margin: 0 0 12px;
  color: var(--gh-green);
  font-size: 0.92rem;
  font-weight: 500;
  letter-spacing: 0.14em;
}

.gh-bansou-course .gh-hero-title {
  margin: 0;
  color: var(--gh-text);
  font-size: clamp(1.8rem, 4vw, 2.65rem);
  font-weight: 500;
  line-height: 1.55;
}

.gh-bansou-course .gh-hero-copy {
  max-width: 760px;
  margin: 24px auto 0;
  font-size: clamp(1rem, 2vw, 1.16rem);
}

.gh-bansou-course .gh-section {
  margin: 0 0 64px;
}

.gh-bansou-course .gh-lead,
.gh-bansou-course .gh-message {
  max-width: 860px;
  margin: 0 auto;
  padding: 38px 44px;
  text-align: center;
  background: #fff;
  border: 1px solid var(--gh-line);
  border-radius: 20px;
}

.gh-bansou-course .gh-heading {
  margin: 0 0 30px;
  padding-bottom: 13px;
  color: var(--gh-text);
  font-size: clamp(1.45rem, 3vw, 2rem);
  font-weight: 500;
  text-align: center;
  border-bottom: 1px solid var(--gh-line);
}

.gh-bansou-course .gh-heading::after {
  display: block;
  width: 80px;
  height: 3px;
  margin: 13px auto -16px;
  background: var(--gh-green);
  content: "";
}

.gh-bansou-course .gh-check-list,
.gh-bansou-course .gh-benefit-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px 22px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.gh-bansou-course .gh-check-list li,
.gh-bansou-course .gh-benefit-list li {
  position: relative;
  padding: 17px 18px 17px 48px;
  background: var(--gh-cream-light);
  border: 1px solid var(--gh-line);
  border-radius: 12px;
}

.gh-bansou-course .gh-check-list li::before {
  position: absolute;
  top: 17px;
  left: 18px;
  color: var(--gh-green);
  font-weight: 700;
  content: "✓";
}

.gh-bansou-course .gh-benefit-list li::before {
  position: absolute;
  top: 17px;
  left: 18px;
  color: var(--gh-green);
  content: "○";
}

.gh-bansou-course .gh-card-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
}

.gh-bansou-course .gh-card {
  padding: 30px 25px;
  background: var(--gh-cream-light);
  border: 1px solid var(--gh-line);
  border-radius: 18px;
}

.gh-bansou-course .gh-card-number {
  display: grid;
  width: 44px;
  height: 44px;
  margin: 0 auto 15px;
  color: #fff;
  font-weight: 500;
  place-items: center;
  background: var(--gh-green);
  border-radius: 50%;
}

.gh-bansou-course .gh-card-title {
  margin: 0 0 12px;
  color: var(--gh-text);
  font-size: 1.12rem;
  font-weight: 500;
  text-align: center;
}

.gh-bansou-course .gh-card p {
  margin: 0;
}

.gh-bansou-course .gh-flow {
  display: grid;
  gap: 16px;
  margin: 0;
  padding: 0;
  counter-reset: gh-step;
  list-style: none;
}

.gh-bansou-course .gh-flow li {
  position: relative;
  min-height: 76px;
  padding: 18px 20px 18px 92px;
  background: #fff;
  border-left: 4px solid var(--gh-green);
  border-radius: 10px;
  box-shadow: 0 7px 24px rgba(85, 93, 89, 0.07);
  counter-increment: gh-step;
}

.gh-bansou-course .gh-flow li::before {
  position: absolute;
  top: 16px;
  left: 22px;
  color: var(--gh-green);
  font-size: 0.88rem;
  font-weight: 700;
  content: "STEP " counter(gh-step);
}

.gh-bansou-course .gh-details {
  overflow: hidden;
  margin: 0;
  background: #fff;
  border: 1px solid var(--gh-line);
  border-radius: 18px;
}

.gh-bansou-course .gh-details-row {
  display: grid;
  grid-template-columns: 210px 1fr;
  border-bottom: 1px solid var(--gh-line);
}

.gh-bansou-course .gh-details-row:last-child {
  border-bottom: 0;
}

.gh-bansou-course .gh-details dt,
.gh-bansou-course .gh-details dd {
  margin: 0;
  padding: 18px 22px;
}

.gh-bansou-course .gh-details dt {
  font-weight: 500;
  background: var(--gh-green-pale);
}

.gh-bansou-course .gh-price {
  color: #6f8d6b;
  font-size: 1.15rem;
  font-weight: 700;
}

.gh-bansou-course .gh-small-note {
  margin: 18px 0 0;
  font-size: 0.9rem;
}

.gh-bansou-course .gh-support {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.gh-bansou-course .gh-support-item {
  padding: 24px;
  background: var(--gh-cream);
  border-radius: 14px;
}

.gh-bansou-course .gh-support-item h3 {
  margin: 0 0 8px;
  color: var(--gh-text);
  font-size: 1.08rem;
  font-weight: 500;
}

.gh-bansou-course .gh-support-item p {
  margin: 0;
}

.gh-bansou-course .gh-message {
  background: var(--gh-cream);
}

.gh-bansou-course .gh-cta {
  padding: 54px 30px;
  text-align: center;
  background: var(--gh-green-pale);
  border-radius: 24px;
}

.gh-bansou-course .gh-cta-title {
  margin: 0 0 12px;
  color: var(--gh-text);
  font-size: clamp(1.45rem, 3vw, 1.9rem);
  font-weight: 500;
}

.gh-bansou-course .gh-cta p {
  margin: 0 0 24px;
}

.gh-bansou-course .gh-button {
  display: inline-flex;
  min-width: 280px;
  min-height: 58px;
  padding: 12px 28px;
  align-items: center;
  justify-content: center;
  color: #fff !important;
  font-weight: 400;
  text-decoration: none !important;
  background: var(--gh-green);
  border: 1px solid var(--gh-green);
  border-radius: 2px;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.gh-bansou-course .gh-button:hover,
.gh-bansou-course .gh-button:focus {
  color: #fff !important;
  opacity: 0.86;
  transform: translateY(-1px);
}

@media (max-width: 767px) {
  .gh-bansou-course .gh-hero {
    margin-bottom: 40px;
    padding: 48px 20px;
  }

  .gh-bansou-course .gh-section {
    margin-bottom: 48px;
  }

  .gh-bansou-course .gh-lead,
  .gh-bansou-course .gh-message {
    padding: 28px 22px;
    text-align: left;
  }

  .gh-bansou-course .gh-check-list,
  .gh-bansou-course .gh-benefit-list,
  .gh-bansou-course .gh-card-grid,
  .gh-bansou-course .gh-support {
    grid-template-columns: 1fr;
  }

  .gh-bansou-course .gh-details-row {
    grid-template-columns: 1fr;
  }

  .gh-bansou-course .gh-details dt {
    padding-bottom: 8px;
  }

  .gh-bansou-course .gh-details dd {
    padding-top: 8px;
  }

  .gh-bansou-course .gh-flow li {
    padding: 54px 18px 18px;
  }

  .gh-bansou-course .gh-flow li::before {
    top: 13px;
    left: 18px;
  }

  .gh-bansou-course .gh-button {
    width: 100%;
    min-width: 0;
  }
}
